#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "parser.h"

/*
 * Binary Data File Reader
 *
 * Reads a custom binary format (.dat files) and prints the contents.
 * The format is documented in parser.h.
 *
 * The reader also performs integrity checks:
 * - Validates checksums
 * - Computes a simple hash of all item data
 * - Reports statistics about the dataset
 *
 * NOTE: This version works around a bug in the pre-compiled
 * libparser.so: parser_next_item() allocates a buffer of
 * (uint16_t)(data_len + 1) bytes and then reads data_len bytes into
 * it.  When data_len == 0xFFFF the 16-bit addition wraps to zero and
 * the fortified read aborts the process ("buffer overflow detected").
 * The wrapper below peeks at each item header and parses such items
 * manually with proper bounds checks; all other items are still
 * handled by the library.
 */

typedef struct {
    uint16_t id;
    uint32_t data_hash;
    size_t data_len;
} item_summary_t;

/* Compute a simple FNV-1a hash of the item data */
static uint32_t compute_data_hash(parsed_item_t *item) {
    uint32_t hash = 2166136261U;
    for (uint16_t i = 0; i < item->data_len; i++) {
        hash ^= item->data[i];
        hash *= 16777619U;
    }
    return hash;
}

/* Print a summary of the dataset */
static void print_summary(item_summary_t *summaries, uint32_t count) {
    printf("\n=== Dataset Summary ===\n");
    printf("Total items: %u\n", count);

    size_t total_data = 0;
    for (uint32_t i = 0; i < count; i++) {
        total_data += summaries[i].data_len;
        printf("  Item %u: id=%u, len=%zu, hash=0x%08x\n",
               i, summaries[i].id, summaries[i].data_len,
               summaries[i].data_hash);
    }
    printf("Total data bytes: %zu\n", total_data);
}

/*
 * Safe replacement for parser_next_item().
 *
 * Returns 1 on success, 0 if no more items, -1 on error -- the same
 * contract as parser_next_item(), but without the crash on items
 * whose data_len is 0xFFFF.
 */
static int safe_next_item(parser_ctx_t *ctx, parsed_item_t *item) {
    unsigned char hdr[4];
    long pos;
    size_t n;

    if (!ctx || !ctx->fp || !item)
        return -1;

    /* No more items (matches the library's behaviour). */
    if (ctx->current_item >= ctx->num_items)
        return 0;

    /* Peek at the 4-byte item header (id and data_len, big endian). */
    pos = ftell(ctx->fp);
    if (pos < 0)
        return parser_next_item(ctx, item);

    n = fread(hdr, 1, sizeof(hdr), ctx->fp);
    if (fseek(ctx->fp, pos, SEEK_SET) != 0)
        return parser_next_item(ctx, item);

    if (n < sizeof(hdr)) {
        /* Truncated item header: report an error instead of letting
         * the library terminate the whole process. */
        return -1;
    }

    uint16_t data_len = (uint16_t)(((uint16_t)hdr[2] << 8) | hdr[3]);
    if (data_len != 0xFFFFu) {
        /* This item is safe for the library to parse. */
        return parser_next_item(ctx, item);
    }

    /*
     * data_len == 0xFFFF triggers the buffer-size wraparound bug in
     * libparser.so, so parse this item manually.  The header bytes
     * have already been validated above; consume them now.
     */
    uint16_t item_id = (uint16_t)(((uint16_t)hdr[0] << 8) | hdr[1]);

    if (fread(hdr, 1, 4, ctx->fp) != 4)
        return -1;

    /* Use a wide (size_t) addition so the size cannot wrap. */
    uint8_t *buf = malloc((size_t)data_len + 1u);
    if (!buf)
        return -1;

    if (fread(buf, 1, data_len, ctx->fp) != data_len) {
        free(buf);
        return -1;
    }
    buf[data_len] = '\0';

    item->item_id = item_id;
    item->data_len = data_len;
    item->data = buf;
    ctx->current_item++;
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file.dat>\n", argv[0]);
        return 1;
    }

    /* Open and parse the file */
    parser_ctx_t *ctx = parser_create(argv[1]);
    if (!ctx) {
        fprintf(stderr, "Failed to open file: %s\n", argv[1]);
        return 1;
    }

    printf("Dataset: %u items, flags=0x%04x\n", ctx->num_items, ctx->flags);
    fflush(stdout);

    /* Allocate space for item summaries */
    item_summary_t *summaries = malloc(ctx->num_items * sizeof(item_summary_t));
    if (!summaries && ctx->num_items > 0) {
        fprintf(stderr, "Failed to allocate summaries\n");
        parser_destroy(ctx);
        return 1;
    }

    /* Read all items (using the crash-safe wrapper) */
    uint32_t item_count = 0;
    parsed_item_t item;
    int rc;

    while ((rc = safe_next_item(ctx, &item)) == 1) {
        if (item_count < ctx->num_items) {
            summaries[item_count].id = item.item_id;
            summaries[item_count].data_len = item.data_len;
            summaries[item_count].data_hash = compute_data_hash(&item);
        }
        item_count++;
        parser_free_item(&item);
    }

    if (rc < 0) {
        fprintf(stderr, "Error parsing item %u\n", item_count);
        free(summaries);
        parser_destroy(ctx);
        return 1;
    }

    /* Read and verify checksum */
    uint32_t expected_checksum = parser_read_checksum(ctx);
    uint32_t computed = 0;
    for (uint32_t i = 0; i < item_count; i++) {
        /* Re-read items to compute checksum...
         * Actually, we already have the data, but it was freed.
         * For a proper implementation, we'd need to keep the data.
         * For now, just trust the parser. */
    }
    (void)expected_checksum;
    (void)computed;

    print_summary(summaries, item_count);

    free(summaries);
    parser_destroy(ctx);

    printf("\nProcessing complete.\n");
    return 0;
}
